func testOrcamentoCompraToManyAddOpOrcContratos(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a OrcamentoCompra
	var b, c, d, e Contrato

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, orcamentoCompraDBTypes, false, strmangle.SetComplement(orcamentoCompraPrimaryKeyColumns, orcamentoCompraColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*Contrato{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, contratoDBTypes, false, strmangle.SetComplement(contratoPrimaryKeyColumns, contratoColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*Contrato{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddOrcContratos(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if !queries.Equal(a.OrcID, first.OrcID) {
			t.Error("foreign key was wrong value", a.OrcID, first.OrcID)
		}
		if !queries.Equal(a.OrcID, second.OrcID) {
			t.Error("foreign key was wrong value", a.OrcID, second.OrcID)
		}

		if first.R.Orc != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Orc != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.OrcContratos[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.OrcContratos[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.OrcContratos().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}

