func testOrcamentoCompraToManyRemoveOpOrcContratos(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a OrcamentoCompra
	var b, c, d, e Contrato

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, orcamentoCompraDBTypes, false, strmangle.SetComplement(orcamentoCompraPrimaryKeyColumns, orcamentoCompraColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*Contrato{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, contratoDBTypes, false, strmangle.SetComplement(contratoPrimaryKeyColumns, contratoColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.AddOrcContratos(ctx, tx, true, foreigners...)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.OrcContratos().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 4 {
		t.Error("count was wrong:", count)
	}

	err = a.RemoveOrcContratos(ctx, tx, foreigners[:2]...)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.OrcContratos().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.OrcID) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.OrcID) {
		t.Error("want c's foreign key value to be nil")
	}

	if b.R.Orc != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.Orc != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.Orc != &a {
		t.Error("relationship to a should have been preserved")
	}
	if e.R.Orc != &a {
		t.Error("relationship to a should have been preserved")
	}

	if len(a.R.OrcContratos) != 2 {
		t.Error("should have preserved two relationships")
	}

	// Removal doesn't do a stable deletion for performance so we have to flip the order
	if a.R.OrcContratos[1] != &d {
		t.Error("relationship to d should have been preserved")
	}
	if a.R.OrcContratos[0] != &e {
		t.Error("relationship to e should have been preserved")
	}
}

