func testOrcamentoCompraToOneSetOpUsuarioUsingUsu(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a OrcamentoCompra
	var b, c Usuario

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, orcamentoCompraDBTypes, false, strmangle.SetComplement(orcamentoCompraPrimaryKeyColumns, orcamentoCompraColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &b, usuarioDBTypes, false, strmangle.SetComplement(usuarioPrimaryKeyColumns, usuarioColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &c, usuarioDBTypes, false, strmangle.SetComplement(usuarioPrimaryKeyColumns, usuarioColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	for i, x := range []*Usuario{&b, &c} {
		err = a.SetUsu(ctx, tx, i != 0, x)
		if err != nil {
			t.Fatal(err)
		}

		if a.R.Usu != x {
			t.Error("relationship struct not set to correct value")
		}

		if x.R.UsuOrcamentoCompras[0] != &a {
			t.Error("failed to append to foreign relationship struct")
		}
		if !queries.Equal(a.UsuID, x.UsuID) {
			t.Error("foreign key was wrong value", a.UsuID)
		}

		zero := reflect.Zero(reflect.TypeOf(a.UsuID))
		reflect.Indirect(reflect.ValueOf(&a.UsuID)).Set(zero)

		if err = a.Reload(ctx, tx); err != nil {
			t.Fatal("failed to reload", err)
		}

		if !queries.Equal(a.UsuID, x.UsuID) {
			t.Error("foreign key was wrong value", a.UsuID, x.UsuID)
		}
	}
}

